class Matematicas:
    @staticmethod
    def es_primo(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

print(Matematicas.es_primo(7))    # True
print(Matematicas.es_primo(10))   # False

