class RangoPersonalizado:
    def __init__(self, inicio, fin):
        self.inicio = inicio
        self.fin = fin

    def __iter__(self):
        self.actual = self.inicio
        return self

    def __next__(self):
        if self.actual >= self.fin:
            raise StopIteration
        valor = self.actual
        self.actual += 1
        return valor

r = RangoPersonalizado(1, 5)
for x in r:
    print(x)   # 1, 2, 3, 4

