class Solver:
    def __init__(self, f, tol=1e-8, max_iter=100):
        self.f = f
        self.tol = tol
        self.max_iter = max_iter

    def resolver(self):
        raise NotImplementedError("Las subclases deben implementar resolver")

class SolverBiseccion(Solver):
    def __init__(self, f, a, b, tol=1e-8, max_iter=100):
        super().__init__(f, tol, max_iter)
        self.a = a
        self.b = b

    def resolver(self):
        for k in range(self.max_iter):
            c = (self.a + self.b) / 2
            if abs(self.f(c)) < self.tol:
                return c, k
            if self.f(self.a) * self.f(c) < 0:
                self.b = c
            else:
                self.a = c
        return c, self.max_iter

solver = SolverBiseccion(lambda x: x**3 - x - 2, 1, 2)
raiz, iters = solver.resolver()
print(f"Raíz: {raiz:.10f}, iteraciones: {iters}")

