class SolverBiseccion:
    def __init__(self, f, a, b):
        self.f, self.a, self.b = f, a, b

    def resolver(self, tol=1e-8):
        for k in range(100):
            c = (self.a + self.b) / 2
            if abs(self.f(c)) < tol:
                return c, k
            if self.f(self.a) * self.f(c) < 0:
                self.b = c
            else:
                self.a = c
        return c, 100

class SolverNewton:
    def __init__(self, f, df, x0):
        self.f, self.df, self.x0 = f, df, x0

    def resolver(self, tol=1e-8):
        x = self.x0
        for k in range(100):
            x_nuevo = x - self.f(x) / self.df(x)
            if abs(x_nuevo - x) < tol:
                return x_nuevo, k
            x = x_nuevo
        return x, 100

f = lambda x: x**3 - x - 2
df = lambda x: 3*x**2 - 1

solvers = [
    SolverBiseccion(f, 1, 2),
    SolverNewton(f, df, 1.5)
]

for s in solvers:
    raiz, k = s.resolver()
    print(f"{type(s).__name__}: raíz = {raiz:.10f}, iter = {k}")

