class Historial:
    def __init__(self):
        self.iteraciones = []

    def agregar(self, k, x, error):
        self.iteraciones.append({"k": k, "x": x, "error": error})

    def ultimo_error(self):
        if not self.iteraciones:
            return None
        return self.iteraciones[-1]["error"]

class SolverBiseccion:
    def __init__(self, f, a, b, tol=1e-8):
        self.f = f
        self.a = a
        self.b = b
        self.tol = tol
        self.historial = Historial()   # composición

    def resolver(self):
        for k in range(100):
            c = (self.a + self.b) / 2
            error = (self.b - self.a) / 2
            self.historial.agregar(k, c, error)
            if error < self.tol:
                return c, k
            if self.f(self.a) * self.f(c) < 0:
                self.b = c
            else:
                self.a = c
        return c, 100

solver = SolverBiseccion(lambda x: x**3 - x - 2, 1, 2)
raiz, k = solver.resolver()
print(f"Raíz: {raiz:.10f}")
print(f"Iteraciones: {k}")
print(f"Historial: {len(solver.historial.iteraciones)} entradas")

